    $gr=$app->goodsReceiving()->createDraft($owner,['purchase_id'=>$po,'receipt_key'=>key58(),'reference_no'=>key58(),'location_id'=>$location,'items'=>[['purchase_item_id'=>$app->purchaseOrders()->items($po)[0]['id'],'quantity'=>$received]]])['receipt_id'];$app->goodsReceiving()->confirm($owner,$gr);
