    $adj=$app->supplierAdjustmentService();$credit=$adj->createCreditDraft($owner,['document_key'=>key58(),'supplier_id'=>$supplier,'invoice_id'=>$invoice,'credit_no'=>key58(),'amount_original'=>$creditAmount,'reason'=>'Original credit linked to returned goods'])['adjustment_id'];$adj->submit($owner,'credit',$credit);$adj->approve($owner,'credit',$credit);$adj->post($owner,'credit',$credit);
    $returns=$app->purchaseReturnService();$return=$returns->createDraft($owner,['document_key'=>key58(),'supplier_id'=>$supplier,'purchase_id'=>$po,'goods_receipt_id'=>$gr,'reason'=>'Supplier return that received an attributed credit','items'=>[['goods_receipt_item_id'=>$app->goodsReceipts()->items($gr)[0]['id'],'quantity'=>$returned,'reason'=>'Supplier collected goods']]])['return_id'];$returns->submit($owner,$return);$returns->approve($owner,$return);$returns->confirm($owner,$return,key58());
