function correction58(array $f,string $amount,string $quantity):int{global$app,$owner;$s=$app->supplierCreditReturnCorrectionService();$id=$s->createDraft($owner,['document_key'=>key58(),'supplier_id'=>$f['supplier']??$GLOBALS['supplier'],'credit_id'=>$f['credit'],'purchase_return_id'=>$f['return'],'purchase_return_credit_link_id'=>$f['link'],'amount_original'=>$amount,'quantity'=>$quantity,'reason'=>'Supplier credit must be corrected after documented return reversal','evidence_reference'=>'Supplier statement '.key58()])['correction_id'];$s->submit($owner,$id);$s->approve($owner,$id);return$id;}
