    ok58($stockBefore===$pdo->query('SELECT product_id,location_id,qty_base FROM stock_balances ORDER BY id')->fetchAll() && $cashBefore===(int)$pdo->query("SELECT COUNT(*) FROM payments WHERE payment_purpose='supplier_payment'")->fetchColumn(),'financial correction creates neither automatic stock restoration nor supplier cash movement');
