    $recoverable=fixture58('4','10','2','4','2','40');$recoverable['supplier']=$supplier;$before=balance58($recoverable['invoice']);$recoverableId=correction58($recoverable,'2','1');$service->post($owner,$recoverableId);$after=balance58($recoverable['invoice']);
